#!/usr/bin/env python3
"""HTTP server with rate-limited /api/time endpoint."""

import time
import json
from http.server import HTTPServer, BaseHTTPRequestHandler
from urllib.parse import urlparse

# Simple in-memory rate limiter: dict of IP -> (count, window_start)
# Each client gets 5 requests per 60 seconds.
rate_limit = {}


def is_rate_limited(ip: str) -> bool:
    """Check if the client has exceeded the rate limit."""
    now = time.time()
    entry = rate_limit.get(ip)
    if entry is None:
        rate_limit[ip] = [0, now]
        return False
    count, window_start = entry
    # If the window has passed, reset the counter
    if now - window_start >= 60:
        rate_limit[ip] = [count, now]
        return False
    # If at limit, return True
    if count >= 5:
        return True
    # Increment count
    rate_limit[ip][0] = count + 1
    return False


def handle_request(request: BaseHTTPRequestHandler):
    """Handle HTTP requests."""
    parsed = urlparse(request.path)
    path = parsed.path

    if path == "/api/time":
        # Check rate limit by client IP
        ip = request.client[0] if request.client else "unknown"
        if is_rate_limited(ip):
            response = {
                "error": "rate_limit_exceeded",
                "message": "Too many requests. Please try again later."
            }
            response["status"] = 429
            response["retry_after"] = 60
            response["headers"] = {
                "Retry-After": "60"
            }
            return response

        # Get current time
        now = int(time.time())
        response = {
            "now": now
        }
        response["status"] = 200
        response["headers"] = {
            "Content-Type": "application/json"
        }
        return response

    # For any other path, return 404
    response = {
        "error": "not_found",
        "message": "Endpoint not found"
    }
    response["status"] = 404
    response["headers"] = {
        "Content-Type": "application/json"
    }
    return response


def run_server(port: int = 8080):
    server = HTTPServer(("0.0.0.0", port), BaseHTTPRequestHandler)
    print(f"Server starting on port {port}...")
    try:
        server.serve_forever()
    except KeyboardInterrupt:
        print("\nServer stopped.")


if __name__ == "__main__":
    run_server()

// throttle.ts - Throttle function wrapper

/**
 * Returns a throttled version of the given function.
 * The function will be called at most `maxPerWindow` times within `windowMs`
 * milliseconds. Excess calls are silently skipped.
 *
 * @param fn - The function to throttle
 * @param maxPerWindow - Maximum number of calls allowed per window
 * @param windowMs - Time window in milliseconds
 * @returns A throttled function that wraps `fn`
 */
export function throttle(fn: () => void, maxPerWindow: number, windowMs: number): () => void {
    const calls = 0;
    const windowStart = Date.now();
    const max = maxPerWindow;
    const window = windowMs;

    return function throttledFn(): void {
        const now = Date.now();
        // If enough time has passed since the last call, allow the function to run
        if (now - windowStart >= window) {
            calls = 0;
            windowStart = now;
            fn();
        } else {
            // Skip this call
            return;
        }
    };
}

// Self-test
if (require.main === module) {
    // Test that the throttle function works correctly
    const throttled = throttle(() => {
        console.log("Function called");
    }, 5, 1000); // 5 calls per 1 second

    const calls = 0;
    const originalFn = throttled;

    // Call the throttled function multiple times
    for (let i = 0; i < 10; i++) {
        originalFn();
        calls++;
        if (calls >= 5) {
            console.log(`Call ${calls} - throttled (should be skipped)`);
        }
    }

    console.log(`Total calls made: ${calls}`);
    console.log("Self-test passed:", calls <= 5);
}

